-- 0148 current human workflow context. Synthetic SQL session/MFA fixture only; NOT real Auth acceptance.
begin;
-- The ordinary SQL harness has minimal auth.users only. This transaction-scoped
-- schema stand-in is created ONLY when absent; real GoTrue acceptance is separate.
create table if not exists auth.sessions(id uuid primary key,user_id uuid not null references auth.users(id),not_after timestamptz);
create function pg_temp.id(n int) returns uuid language sql immutable as $$select ('99143000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.ok(v boolean,m text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'ASSERTION: %',m;end if;end$$;
insert into auth.users(id,email) select pg_temp.id(n),'custody-'||n||'@example.invalid' from generate_series(1,5)n;
insert into public.users(id,email,is_axiom_internal) select pg_temp.id(n),'custody-'||n||'@example.invalid',n in(2,3) from generate_series(1,5)n;
insert into public.tenants(id,slug,name) values(pg_temp.id(11),'custody-143-a','Synthetic custody A'),(pg_temp.id(12),'custody-143-b','Synthetic custody B');
insert into public.tenant_users(tenant_id,user_id,role) values(pg_temp.id(11),pg_temp.id(1),'owner'),(pg_temp.id(11),pg_temp.id(2),'founder'),(pg_temp.id(11),pg_temp.id(3),'axiom_analyst'),(pg_temp.id(11),pg_temp.id(4),'viewer'),(pg_temp.id(12),pg_temp.id(5),'owner');
insert into auth.sessions(id,user_id,not_after) select pg_temp.id(100+n),pg_temp.id(n),null from generate_series(1,5)n;
insert into public.user_mfa_factors(id,user_id,factor_type,status,secret_encrypted) select pg_temp.id(40+n),pg_temp.id(n),'totp','active','synthetic-sealed' from generate_series(1,5)n;
insert into public.workload_identities(id,tenant_id,agent_name,spiffe_id,status) values(pg_temp.id(31),pg_temp.id(11),'parikshan','spiffe://local.axiom/agent/parikshan','active');
create function pg_temp.policy() returns jsonb language sql as $$select jsonb_build_object('version',1,'policyId',pg_temp.id(21),'tenantId',pg_temp.id(11),'mode','operator_managed','nominatedOperatorId',pg_temp.id(3),'targetWorkloadId',pg_temp.id(31),'servicePrincipals',jsonb_build_object('producer','spiffe://local.axiom/service/assessment-dispatch-producer','controller','spiffe://local.axiom/controller/assessment'),'validity',jsonb_build_object('kind','until_revoked','reviewDueAt',1),'actionClass','assessment_dispatch_key_custody','keyPolicy',jsonb_build_object('primary','axiom-local-dispatch://'||pg_temp.id(11)||'/'||pg_temp.id(21)||'/versions/1','readable',jsonb_build_array('axiom-local-dispatch://'||pg_temp.id(11)||'/'||pg_temp.id(21)||'/versions/1')),'keyPolicySha256','2e67deedbb81f6897d5f5a48a76734faaf79e6e86bd54285f03d9114a4e0f30b','deploymentBindingSha256',repeat('b',64),'reason','Explicit local custody limitation','acceptedLimitations',jsonb_build_array('hardware_backing_unverified'),'statutoryComplianceAsserted',false,'ownershipVerified',false)$$;
-- Above key-policy fingerprint is independently generated by frozen TS LocalKeyPolicy.
select pg_temp.ok(controller_security.local143_policy(controller_security.canonical_questionnaire_json(pg_temp.policy()))=pg_temp.policy(),'TS key fingerprint matches SQL canonical derivation');
-- Syntax parity only: actual issuer/peer must still pin the configured trusted principal.
do $$declare d text;k text;v jsonb;path text;begin
 foreach d in array array['..','.local','local.','-local','local-','a..b','LOCAL','a b',repeat('a',256)] loop
  foreach k in array array['producer','controller'] loop
   path:=case k when 'producer' then 'service/assessment-dispatch-producer' else 'controller/assessment' end;
   v:=jsonb_set(pg_temp.policy(),array['servicePrincipals',k],to_jsonb('spiffe://'||d||'/'||path));
   begin perform controller_security.local143_policy(controller_security.canonical_questionnaire_json(v));
    raise exception 'invalid custody service domain accepted';
   exception when invalid_parameter_value then null;end;
  end loop;
 end loop;
 foreach d in array array['a','local.axiom','a-b.c',repeat('a',255)] loop
  v:=jsonb_set(jsonb_set(pg_temp.policy(),'{servicePrincipals,producer}',to_jsonb('spiffe://'||d||'/service/assessment-dispatch-producer')),'{servicePrincipals,controller}',to_jsonb('spiffe://'||d||'/controller/assessment'));
  perform pg_temp.ok(controller_security.local143_policy(controller_security.canonical_questionnaire_json(v))=v,'canonical service domain accepted');
 end loop;
end$$;
create function pg_temp.request(k int,transition text,previous uuid default null) returns text language sql as $$select controller_security.canonical_questionnaire_json(jsonb_build_object('version',1,'operationKey',pg_temp.id(k),'transition',transition,'policyText',controller_security.canonical_questionnaire_json(pg_temp.policy()),'policySha256',encode(sha256(convert_to(controller_security.canonical_questionnaire_json(pg_temp.policy()),'UTF8')),'hex'),'previousEventId',previous,'nextReviewDueAt',case when transition='review' then to_jsonb(floor(extract(epoch from clock_timestamp())*1000)::bigint+86400000) else 'null'::jsonb end,'reason','Explicit synthetic custody decision','confirmed',true))$$;
create function pg_temp.challenge(actor int,request_text text) returns uuid language plpgsql as $$declare c uuid:=gen_random_uuid();r jsonb:=request_text::jsonb;binding text;begin
 binding:=encode(sha256(convert_to(controller_security.canonical_questionnaire_json(jsonb_build_array('axiom.local-custody.transition',1,pg_temp.id(11)::text,pg_temp.id(actor)::text,pg_temp.id(100+actor)::text,encode(sha256(convert_to(request_text,'UTF8')),'hex'))),'UTF8')),'hex');
 insert into public.mfa_challenges(id,user_id,tenant_id,factor_id,purpose,bound_resource_ref,bound_payload_sha256,created_at,expires_at,satisfied_at,consumed_at,consumed_for,satisfied_with) values(c,pg_temp.id(actor),pg_temp.id(11),pg_temp.id(40+actor),'local_custody_policy',r->>'operationKey',binding,clock_timestamp()-interval '2 seconds',clock_timestamp()+interval '4 minutes 50 seconds',clock_timestamp()-interval '1 second',clock_timestamp(),r->>'operationKey','totp');return c;
end$$;
create function pg_temp.write(request_text text,actor int,challenge uuid default null) returns jsonb language plpgsql as $$declare c uuid:=coalesce(challenge,pg_temp.challenge(actor,request_text));v jsonb;prior text:=current_user;begin
 set local role human_action_writer;v:=public.record_local_custody_policy_event(pg_temp.id(11),pg_temp.id(actor),pg_temp.id(100+actor),request_text,c);execute format('set local role %I',prior);return v;
 exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.refused(request_text text,actor int,code text default '42501',challenge uuid default null) returns void language plpgsql as $$declare n bigint;begin
 select count(*) into n from public.audit_ledger;
 begin perform pg_temp.write(request_text,actor,challenge);set constraints all immediate;exception when others then if sqlstate=code then perform pg_temp.ok((select count(*)=n from public.audit_ledger),'refusal leaves ledger unchanged');return;end if;raise;end;
 raise exception 'unexpected custody authorization';end$$;
create temporary table custody_saved(kind text primary key,v jsonb,request_text text);
grant select on custody_saved to service_role,human_action_writer;
select pg_temp.refused(pg_temp.request(61,'request'),4);
select pg_temp.refused(pg_temp.request(61,'request'),2); -- founder cannot invent ordinary customer request
insert into custody_saved values('request',pg_temp.write(pg_temp.request(61,'request'),1),pg_temp.request(61,'request'));
set constraints all immediate;set constraints all deferred;
select pg_temp.ok(pg_temp.write(pg_temp.request(61,'request'),1)->'replayed'='true'::jsonb,'exact positive replay creates no receipt');
select pg_temp.refused((pg_temp.request(61,'request')::jsonb||jsonb_build_object('reason','Changed'))::text,1,'22023');
select pg_temp.refused(controller_security.canonical_questionnaire_json(pg_temp.request(61,'request')::jsonb||jsonb_build_object('reason','Changed')),1,'23505');
select pg_temp.refused(pg_temp.request(61,'request'),5); -- foreign customer owner has no tenant authority
select pg_temp.refused(pg_temp.request(62,'activate',(select (v->>'eventId')::uuid from custody_saved where kind='request')),3,'23514');
do $$begin begin update public.tenant_users set role='viewer' where tenant_id=pg_temp.id(11) and user_id=pg_temp.id(1);perform pg_temp.write(pg_temp.request(62,'approve',(select (v->>'eventId')::uuid from custody_saved where kind='request')),2);raise exception 'retired customer owner request accepted';exception when insufficient_privilege then null;end;end$$;
insert into custody_saved select 'approve',pg_temp.write(pg_temp.request(62,'approve',(v->>'eventId')::uuid),2),pg_temp.request(62,'approve',(v->>'eventId')::uuid) from custody_saved where kind='request';
select pg_temp.refused(pg_temp.request(63,'activate',(select (v->>'eventId')::uuid from custody_saved where kind='approve')),2);
do $$begin begin update public.users set is_axiom_internal=false where id=pg_temp.id(2);perform pg_temp.write(pg_temp.request(63,'activate',(select (v->>'eventId')::uuid from custody_saved where kind='approve')),3);raise exception 'retired founder approval accepted';exception when insufficient_privilege then null;end;end$$;
insert into custody_saved select 'activate',pg_temp.write(pg_temp.request(63,'activate',(v->>'eventId')::uuid),3),pg_temp.request(63,'activate',(v->>'eventId')::uuid) from custody_saved where kind='approve';
set constraints all immediate;set constraints all deferred;
select pg_temp.ok((select state='active' and activation_epoch=1 from public.local_custody_policy_heads where policy_id=pg_temp.id(21)),'ordered three-stage authority active');
select pg_temp.ok((select count(*)=3 from public.audit_ledger where tenant_id=pg_temp.id(11)),'exactly three scoped human receipts');

-- No table or credential privilege is granted by the read-only context API.
select pg_temp.ok(not has_table_privilege('authenticated','public.local_custody_policy_versions','SELECT'),'authenticated cannot directly read policy rows');
select pg_temp.ok(not has_table_privilege('human_action_writer','public.local_custody_policy_events','SELECT'),'human writer cannot directly read event rows');
select pg_temp.ok(not has_function_privilege('authenticated','public.read_local_custody_operator_context(uuid,uuid,uuid,uuid,uuid,bigint)','EXECUTE'),'authenticated cannot forge context RPC actors');
select pg_temp.ok(not has_function_privilege('axiom_assessment_controller','public.read_local_custody_operator_context(uuid,uuid,uuid,uuid,uuid,bigint)','EXECUTE'),'controller cannot use human context');
do $$declare denied boolean:=false;begin
 begin set local role authenticated;perform 1 from public.local_custody_policy_versions;exception when insufficient_privilege then denied:=true;end;reset role;
 perform pg_temp.ok(denied,'actual authenticated role cannot SELECT protected context tables');
end$$;
create function pg_temp.context(actor int,tenant int default 11,session_actor int default null,policy int default null) returns jsonb language plpgsql as $$declare v jsonb;prior text:=current_user;begin
 set local role service_role;v:=public.read_local_custody_operator_context(pg_temp.id(tenant),pg_temp.id(actor),pg_temp.id(100+coalesce(session_actor,actor)),case when policy is null then null else pg_temp.id(policy) end,null,null);execute format('set local role %I',prior);return v;
 exception when others then execute format('set local role %I',prior);raise;end$$;
select pg_temp.ok(pg_temp.context(1)->'canRequest'='true'::jsonb,'owner discovers request workflow');
select pg_temp.ok(pg_temp.context(2)->'canRequest'='false'::jsonb and pg_temp.context(2)->'requestModes'='[]'::jsonb,'founder cannot invent ordinary owner request');
select pg_temp.ok(pg_temp.context(1)->'requestModes'='["operator_managed"]'::jsonb,'ordinary owner request modes explicit');
update public.tenants set is_demo=true where id=pg_temp.id(11);
select pg_temp.ok(pg_temp.context(2)->'requestModes'='["local_demo"]'::jsonb,'demo founder can request only explicit demo profile');
update public.tenants set is_demo=false where id=pg_temp.id(11);
select pg_temp.ok(pg_temp.context(3)->'rows'->0->>'policyId'=pg_temp.id(21)::text,'nominated internal operator can discover policy');
select pg_temp.ok(pg_temp.context(2,11,null,21)#>>'{rows,0,head,state}'='active','founder sees current active head');
select pg_temp.ok(pg_temp.context(1,11,null,21)#>>'{history,0,transition}'='activate','history includes other authorized actors latest receipt');
select pg_temp.ok(jsonb_array_length(pg_temp.context(1,11,null,21)->'history')=3,'all ordered quorum receipts readable');
select pg_temp.ok(pg_temp.context(1)#>>'{rows,0,reviewOverdue}'='true','overdue reminder does not revoke policy');
select pg_temp.ok(pg_temp.context(1)#>>'{rows,0,head,state}'='active','overdue state stays active');
select pg_temp.ok(pg_temp.context(1)#>>'{rows,0,actions,0}' is not null,'owner can review or revoke');
do $$declare denied boolean;before_count bigint;begin
 select count(*) into before_count from public.audit_ledger;
 denied:=false;begin perform pg_temp.context(4);exception when insufficient_privilege then denied:=true;end;perform pg_temp.ok(denied,'viewer context refused');
 denied:=false;begin perform pg_temp.context(5);exception when insufficient_privilege then denied:=true;end;perform pg_temp.ok(denied,'foreign tenant actor refused');
 denied:=false;begin perform pg_temp.context(1,11,2);exception when insufficient_privilege then denied:=true;end;perform pg_temp.ok(denied,'foreign session refused');
 denied:=false;begin update auth.sessions set not_after=clock_timestamp()-interval '1 second' where id=pg_temp.id(101);perform pg_temp.context(1);exception when insufficient_privilege then denied:=true;end;perform pg_temp.ok(denied,'expired session refused');
 denied:=false;begin delete from auth.sessions where id=pg_temp.id(101);perform pg_temp.context(1);exception when insufficient_privilege then denied:=true;end;perform pg_temp.ok(denied,'missing revoked session refused');
 denied:=false;begin update public.users set is_axiom_internal=false where id=pg_temp.id(2);perform pg_temp.context(2);exception when insufficient_privilege then denied:=true;end;perform pg_temp.ok(denied,'offboarded founder refused');
 denied:=false;begin update public.local_custody_policy_heads set state='revoked' where policy_id=pg_temp.id(21);set constraints all immediate;exception when check_violation then denied:=true;end;perform pg_temp.ok(denied,'context addition does not weaken reciprocal head guard');
 perform pg_temp.ok((select count(*)=before_count from public.audit_ledger),'read context and denied reads never mutate ledger');
end$$;

-- Real owner requests produce bounded policy pagination; no fabricated policy rows.
do $$declare n int;p jsonb;ref text;policy_text text;q text;fingerprint text;page jsonb;tail jsonb;begin
 for n in 500..520 loop
  ref:='axiom-local-dispatch://'||pg_temp.id(11)||'/'||pg_temp.id(n)||'/versions/1';
  p:=pg_temp.policy()||jsonb_build_object('policyId',pg_temp.id(n),'keyPolicy',jsonb_build_object('primary',ref,'readable',jsonb_build_array(ref)));
  fingerprint:=encode(sha256(convert_to(controller_security.canonical_questionnaire_json(jsonb_build_array('axiom.local.dispatch.policy',1,p->>'tenantId',p->>'policyId',p->>'mode',p->'validity',ref,jsonb_build_array(ref))),'UTF8')),'hex');
  p:=p||jsonb_build_object('keyPolicySha256',fingerprint);policy_text:=controller_security.canonical_questionnaire_json(p);
  q:=controller_security.canonical_questionnaire_json(pg_temp.request(1000+n,'request')::jsonb||jsonb_build_object('policyText',policy_text,'policySha256',encode(sha256(convert_to(policy_text,'UTF8')),'hex')));
  perform pg_temp.write(q,1);
 end loop;
 page:=pg_temp.context(1);perform pg_temp.ok(jsonb_array_length(page->'rows')=20 and page->>'nextCursor' is not null,'first bounded policy page');
 set local role service_role;tail:=public.read_local_custody_operator_context(pg_temp.id(11),pg_temp.id(1),pg_temp.id(101),null,(page->>'nextCursor')::uuid,null);reset role;
 perform pg_temp.ok(jsonb_array_length(tail->'rows')=2 and tail->'nextCursor'='null'::jsonb,'second bounded policy page');
end$$;
-- History paging follows actual immutable human events and decimal receipt IDs.
do $$declare n int;q text;head uuid;page jsonb;tail jsonb;begin
 for n in 1..22 loop
  select event_id into head from public.local_custody_policy_heads where policy_id=pg_temp.id(21);
  q:=pg_temp.request(2000+n,'review',head);perform pg_temp.write(q,1);
 end loop;
 page:=pg_temp.context(1,11,null,21);perform pg_temp.ok(jsonb_array_length(page->'history')=20 and page->>'nextHistoryCursor' is not null,'first bounded history page');
 set local role service_role;tail:=public.read_local_custody_operator_context(pg_temp.id(11),pg_temp.id(1),pg_temp.id(101),pg_temp.id(21),null,(page->>'nextHistoryCursor')::bigint);reset role;
 perform pg_temp.ok(jsonb_array_length(tail->'history')=5 and tail->'nextHistoryCursor'='null'::jsonb,'second history page preserves earliest quorum events');
 perform pg_temp.ok(page#>>'{rows,0,head,state}'='active' and page#>>'{rows,0,reviewOverdue}'='false','periodic review updates reminder without altering validity');
end$$;
-- A different internal analyst is not a nominated reader.
update public.users set is_axiom_internal=true where id=pg_temp.id(4);
update public.tenant_users set role='axiom_analyst' where user_id=pg_temp.id(4);
select pg_temp.ok(pg_temp.context(4)->'rows'='[]'::jsonb,'non-nominated analyst cannot enumerate policy');
do $$declare denied boolean:=false;begin begin perform pg_temp.context(4,11,null,21);exception when insufficient_privilege then denied:=true;end;perform pg_temp.ok(denied,'non-nominated analyst cannot read exact history');end$$;
select pg_temp.ok(not exists(select 1 from public.verify_ledger(pg_temp.id(11))),'context workflow preserves ledger chain');
rollback;
